package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.workflow.WorkflowNodeType;import org.springframework.stereotype.Component;import java.util.*;
@Component public class ForEachNodeExecutor implements NodeExecutor {private final ObjectMapper mapper;public ForEachNodeExecutor(ObjectMapper m){mapper=m;}public Set<WorkflowNodeType>supportedTypes(){return Collections.singleton(WorkflowNodeType.FOREACH);}public NodeExecutionResult execute(NodeExecutionContext c){try{JsonNode cfg=mapper.readTree(c.getNode().getConfigurationJson());String collection=cfg.path("collectionVariable").asText();Object value=c.getVariables().get(collection);if(!(value instanceof Collection))return NodeExecutionResult.failure("FOREACH_COLLECTION_REQUIRED",false);int max=Math.max(1,c.getExecutionContext().getExecutionBudget().getMaxParallelism());List<?>items=new ArrayList<>((Collection<?>)value);if(items.size()>1000)return NodeExecutionResult.failure("FOREACH_ITEM_LIMIT_EXCEEDED",false);Map<String,Object>u=new LinkedHashMap<>();u.put(c.getNode().getCode()+".items",items);u.put(c.getNode().getCode()+".maxParallelism",max);return NodeExecutionResult.success(mapper.valueToTree(items),null,u);}catch(Exception e){return NodeExecutionResult.failure("FOREACH_CONFIG_INVALID",false);}}}
